class Solution {
public:
    int minSwaps(vector<int>& data) {
        int ones = accumulate(data.begin(), data.end(), 0);
        if (ones == 0) {
            return 0;
        }
        int inWindow = 0;
        int best = 0;
        for (int i = 0; i < static_cast<int>(data.size()); ++i) {
            inWindow += data[i];
            if (i >= ones) {
                inWindow -= data[i - ones];
            }
            if (i >= ones - 1) {
                best = max(best, inWindow);
            }
        }
        return ones - best;
    }
};
